-- =====================================================================
--  Prime Script — Contenu prêt à l'emploi (6/12) : Argumentaires (service × secteur)
--
--  Ce fichier s'importe avec les autres fichiers de database/content/ :
--      php tools/import-content.php
--  (ou, en MySQL : mysql -u ... prime_script < database/content/content.sql
--   si ce fichier a été concaténé dans content.sql).
--
--  Format d'une ligne de contenu (JSON, une ligne par enregistrement) :
--    {"code": "...", "type": "...", "sector": "...", "stage": "...",
--     "service": "...", "title": "...", "position": 10, "content": "<p>…</p>"}
--
--    code     identifiant stable du bloc (réimport = mise à jour, jamais de doublon)
--    type     presentation | accroche | barrage | repondeur | decouverte |
--             argumentaire | preuve | tarif | appel_action | conclusion
--    sector   slug du secteur (architectes, artisans-btp, restauration, services-b2b)
--    stage    slug de l'étape (premier-appel, relance, closing)
--    service  slug du service (site-web, application, automatisation-ia, chatbot-ia)
--    content  HTML simple : <p>, <ul>, <li>, <strong>, <em>
--
--  Convention d'écriture : le texte à dire est en clair, l'aide au commercial
--  est sur une ligne « Conseil : … » en italique (<p><em>Conseil : …</em></p>).
-- =====================================================================

SET NAMES utf8mb4;

{"code": "arg-site-web-architectes", "type": "argumentaire", "sector": "architectes", "service": "site-web", "title": "Argumentaire — Site web · Architectes", "position": 10, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Quand un maître d'ouvrage cherche un architecte dans votre ville, il compare trois sites. Le vôtre doit montrer vos projets avant même qu'il vous appelle.<br><em>Conseil : un site d'architecte n'a pas besoin d'être grand : il doit être beau et à jour.</em></li><li>Une page par projet, avec les photos, le programme et le lieu. C'est ce que regarde un client avant de vous contacter.<br><em>Conseil : une galerie sans texte ne convertit pas. Une fiche projet par réalisation, oui.</em></li><li>Vos photos sont probablement votre meilleur argument. Sur le site, elles sont protégées et elles vous appartiennent.<br><em>Conseil : Instagram reste utile, mais il ne remplace pas un site. Les deux se complètent.</em></li><li>Vous mettez à jour vos projets vous-même, sans dépendre d'un prestataire. Une nouvelle livraison s'ajoute en quelques minutes.<br><em>Conseil : montrez l'interface d'administration côté client, c'est rassurant.</em></li></ul>"}
{"code": "arg-site-web-artisans-btp", "type": "argumentaire", "sector": "artisans-btp", "service": "site-web", "title": "Argumentaire — Site web · Artisans et BTP", "position": 20, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Un particulier qui cherche un artisan dans sa ville lit trois choses : vos réalisations, vos avis et vos garanties. Le site les met côte à côte.<br><em>Conseil : parlez de « rassurer », pas de « crédibilité ». C'est le mot juste.</em></li><li>Un formulaire de demande de devis en trente secondes. Pas cinq écrans, pas de compte à créer.<br><em>Conseil : chaque champ en trop fait perdre des demandes.</em></li><li>Une page par grand chantier type : salle de bain, toiture, extension. C'est ce que les gens tapent sur Google.<br><em>Conseil : c'est concret et ça se comprend immédiatement.</em></li><li>Quand vous envoyez un devis, le client peut le relire sur son téléphone. Le lien remplace le PDF illisible.<br><em>Conseil : un devis lisible réduit les allers-retours au téléphone.</em></li></ul>"}
{"code": "arg-site-web-restauration", "type": "argumentaire", "sector": "restauration", "service": "site-web", "title": "Argumentaire — Site web · Restauration", "position": 30, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>La carte toujours à jour, sans réimprimer et sans appel à votre prestataire. Vous changez un plat, le site suit.<br><em>Conseil : c'est l'argument qui parle le plus vite aux restaurateurs.</em></li><li>La réservation en ligne, y compris le soir et le week-end, quand vous êtes en service ou fermé.<br><em>Conseil : le client décide en dehors des horaires d'ouverture.</em></li><li>Horaires, accès, stationnement, groupes : les réponses aux questions que vous répétez cent fois.<br><em>Conseil : chaque question évitée, c'est une minute de service gagnée.</em></li><li>Un site rapide sur téléphone. Un client affamé ne patiente pas trois secondes.<br><em>Conseil : la vitesse se montre, elle ne s'explique pas. Testez devant le client.</em></li></ul>"}
{"code": "arg-site-web-services-b2b", "type": "argumentaire", "sector": "services-b2b", "service": "site-web", "title": "Argumentaire — Site web · Services B2B", "position": 40, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Aujourd'hui quand un prospect vous cherche sur Google, il doit comprendre en dix secondes ce que vous faites et pour qui.<br><em>Conseil : la clarté est plus rentable que l'esthétique en B2B.</em></li><li>Un bouton de prise de rendez-vous visible partout. C'est la seule action que vous voulez vraiment.<br><em>Conseil : un seul appel à l'action par page. Deux actions, c'est zéro action.</em></li><li>Une page par métier ou par secteur. Une page unique « nos services » ne se positionne sur rien.<br><em>Conseil : en B2B, les acheteurs tapent leur problème, pas votre métier.</em></li><li>Vous voyez ce qui fonctionne : visites, demandes, pages consultées. Sans outil compliqué.<br><em>Conseil : parlez d'analytics respectueuses de la vie privée, c'est vrai et ça rassure.</em></li></ul>"}
{"code": "arg-application-architectes", "type": "argumentaire", "sector": "architectes", "service": "application", "title": "Argumentaire — Application · Architectes", "position": 10, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Aujourd'hui quand vous cherchez un plan dans un dossier, vous ouvrez combien de dossiers avant de le trouver ? Supprimez cette recherche.<br><em>Conseil : le problème est très concret. Ne parlez pas de « GED ».</em></li><li>Un espace projet par chantier : plans, comptes rendus, documents partagés avec le maître d'ouvrage. Chacun voit ce qui le concerne.<br><em>Conseil : la notion de droits par personne est bien comprise par les architectes.</em></li><li>Les réserves et les allers-retours de chantier sont notés au même endroit, avec une photo et une date.<br><em>Conseil : c'est un besoin qui revient dans toutes les agences.</em></li><li>Sur le chantier, vous ouvrez le dossier sur votre téléphone. Pas besoin de revenir au bureau.<br><em>Conseil : le terrain est le lieu de décision, pas le bureau.</em></li></ul>"}
{"code": "arg-application-artisans-btp", "type": "argumentaire", "sector": "artisans-btp", "service": "application", "title": "Argumentaire — Application · Artisans et BTP", "position": 20, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Aujourd'hui quand une demande arrive et que vous êtes sur un chantier, elle attend. Avec l'application, elle arrive au même endroit, avec une photo et une adresse.<br><em>Conseil : l'objectif : une seule boîte, pas trois.</em></li><li>Vos devis se créent depuis une bibliothèque de prix. Vous ajustez, vous envoyez, le client signe en ligne.<br><em>Conseil : la bibliothèque de prix fait gagner du temps dès le deuxième devis.</em></li><li>Les relances partent toutes seules au bout de sept jours. Vous ne perdez plus un devis dans un carnet.<br><em>Conseil : la relance automatique est souvent le gain le plus immédiat.</em></li><li>Le planning de l'équipe est visible sur téléphone. Chacun sait où il va demain matin.<br><em>Conseil : une photo du planning sur le téléphone parle mieux qu'un tableau Excel.</em></li></ul>"}
{"code": "arg-application-restauration", "type": "argumentaire", "sector": "restauration", "service": "application", "title": "Argumentaire — Application · Restauration", "position": 30, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Une seule application pour les réservations, les commandes et les stocks, au lieu d'un cahier et de deux tableurs.<br><em>Conseil : ne dites pas « ERP ». Dites « un seul endroit ».</em></li><li>Le plan de salle se remplit en direct. Le serveur voit les tables libres sans faire le tour de la salle.<br><em>Conseil : c'est un gain visible dès le premier service.</em></li><li>Les stocks se décrémentent avec les plats vendus. Vous savez ce qui manque avant d'ouvrir.<br><em>Conseil : la question « qu'est-ce que je commande demain » se règle en dix secondes.</em></li><li>La réservation vient du site, de Google et du téléphone, toujours dans le même planning.<br><em>Conseil : éviter la double réservation est le vrai gain, avant la statistique.</em></li></ul>"}
{"code": "arg-application-services-b2b", "type": "argumentaire", "sector": "services-b2b", "service": "application", "title": "Argumentaire — Application · Services B2B", "position": 40, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Aujourd'hui votre suivi de devis est dans une boîte mail. Un tableau simple remplacerait déjà trois heures par semaine.<br><em>Conseil : commencez petit : un tableau partagé convainc plus qu'une refonte.</em></li><li>Chaque devis a son statut : envoyé, relancé, signé, perdu. Vous voyez d'un coup d'œil ce qui dort.<br><em>Conseil : c'est le mot « dort » qui déclenche la prise de conscience.</em></li><li>Les relances partent automatiquement aux dates que vous choisissez. Rien ne s'oublie.<br><em>Conseil : un commercial relance mieux quand il n'a pas à y penser.</em></li><li>Vos commerciaux saisissent sur téléphone entre deux rendez-vous, et le bureau voit tout en direct.<br><em>Conseil : la saisie mobile est souvent le point de bascule d'un projet.</em></li></ul>"}
{"code": "arg-automatisation-ia-architectes", "type": "argumentaire", "sector": "architectes", "service": "automatisation-ia", "title": "Argumentaire — Automatisation IA · Architectes", "position": 10, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Aujourd'hui quand un nouveau message arrive, quelqu'un le lit, le trie, puis le recopie dans le dossier. Cette chaîne peut se faire seule.<br><em>Conseil : décrivez la chaîne en trois étapes, comme ici. C'est limpide.</em></li><li>Les comptes rendus de réunion se préparent à partir de vos notes. Vous relisez et vous validez.<br><em>Conseil : il y a toujours une validation humaine. Dites-le avant qu'on vous le demande.</em></li><li>Les relances d'avenant et de facture partent à date fixe, sans y penser.<br><em>Conseil : c'est l'exemple qui parle le plus aux petites structures.</em></li><li>Les demandes entrantes sont classées par type de projet avant même que vous les ouvriez.<br><em>Conseil : on ne parle pas d'IA ici, on parle de tri. C'est plus vendeur.</em></li></ul>"}
{"code": "arg-automatisation-ia-artisans-btp", "type": "argumentaire", "sector": "artisans-btp", "service": "automatisation-ia", "title": "Argumentaire — Automatisation IA · Artisans et BTP", "position": 20, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Quand un particulier remplit le formulaire, la demande devient une fiche, avec un SMS de confirmation et une alerte pour vous.<br><em>Conseil : le premier automatisme à mettre en place, dans presque tous les cas.</em></li><li>Le devis non signé reçoit une relance polie au bout de sept jours, puis quatorze. Vous n'y pensez plus.<br><em>Conseil : c'est souvent le gain le plus direct en chiffre d'affaires.</em></li><li>Les photos du chantier arrivent dans le bon dossier, sans passer par WhatsApp.<br><em>Conseil : le vrai problème des artisans, c'est où sont les photos.</em></li><li>La facture se prépare à partir du devis signé. Vous vérifiez les montants, puis vous envoyez.<br><em>Conseil : la facture est le document que tout le monde déteste faire.</em></li></ul>"}
{"code": "arg-automatisation-ia-restauration", "type": "argumentaire", "sector": "restauration", "service": "automatisation-ia", "title": "Argumentaire — Automatisation IA · Restauration", "position": 30, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Chaque réservation reçoit une confirmation, un rappel la veille, et une demande d'avis le lendemain. Tout se fait sans vous.<br><em>Conseil : c'est simple et ça réduit vraiment le nombre de réservations perdues.</em></li><li>Les commandes de fournisseurs se préparent à partir des stocks bas. Vous validez avant envoi.<br><em>Conseil : un restaurant qui commande à la main commande trop ou trop peu.</em></li><li>Les avis clients arrivent au même endroit, prêts à être repris sur le site.<br><em>Conseil : les avis sont un moteur de réservation, encore faut-il les collecter.</em></li><li>La carte du site se met à jour depuis un simple fichier. Une modification, une sauvegarde, c'est fini.<br><em>Conseil : zéro dépendance au prestataire : c'est ce qu'il veut entendre.</em></li></ul>"}
{"code": "arg-automatisation-ia-services-b2b", "type": "argumentaire", "sector": "services-b2b", "service": "automatisation-ia", "title": "Argumentaire — Automatisation IA · Services B2B", "position": 40, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Aujourd'hui votre commercial recopie les informations d'un formulaire dans son CRM. Cette étape disparaît.<br><em>Conseil : la double saisie est le premier gain accepté par les équipes commerciales.</em></li><li>Les rendez-vous pris en ligne arrivent dans vos agendas, avec un rappel automatique la veille.<br><em>Conseil : moins de rendez-vous manqués, sans relance manuelle.</em></li><li>Le devis signé déclenche la facture et l'ouverture du dossier projet. Personne n'oublie.<br><em>Conseil : la chaîne devis-facture-projet est ce que les PME demandent le plus.</em></li><li>Un rapport hebdomadaire se construit seul à partir de vos outils. Vous le recevez le lundi matin.<br><em>Conseil : un rapport qui arrive tout seul, c'est un rituel d'équipe en plus.</em></li></ul>"}
{"code": "arg-chatbot-ia-architectes", "type": "argumentaire", "sector": "architectes", "service": "chatbot-ia", "title": "Argumentaire — Chatbot IA · Architectes", "position": 10, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Le soir, un visiteur regarde vos projets et veut savoir si vous faites des extensions. L'assistant répond avec vos mots.<br><em>Conseil : l'assistant ne répond que sur ce que vous avez validé. Rassurez sur ce point.</em></li><li>Il recueille le programme, la surface et la commune, puis vous transmet une demande déjà qualifiée.<br><em>Conseil : qualifié veut dire : vous savez si ça vaut un rendez-vous.</em></li><li>Quand la question dépasse son périmètre, il passe la main avec un résumé. Vous rappelez en sachant de quoi il s'agit.<br><em>Conseil : le passage à l'humain est le point qui fait signer les architectes.</em></li></ul>"}
{"code": "arg-chatbot-ia-artisans-btp", "type": "argumentaire", "sector": "artisans-btp", "service": "chatbot-ia", "title": "Argumentaire — Chatbot IA · Artisans et BTP", "position": 20, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Un particulier qui visite votre site le dimanche soir pose trois questions. L'assistant répond à sa place, tout de suite.<br><em>Conseil : le dimanche soir est le moment où les particuliers font leurs recherches.</em></li><li>Il demande la commune, le type de travaux et le délai souhaité. Vous recevez des demandes triées.<br><em>Conseil : c'est le tri qui fait gagner du temps, pas la conversation.</em></li><li>Il répond uniquement sur votre zone d'intervention et vos tarifs de départ. Pas d'engagement de prix.<br><em>Conseil : l'assistant ne donne jamais de prix ferme. Dites-le clairement.</em></li></ul>"}
{"code": "arg-chatbot-ia-restauration", "type": "argumentaire", "sector": "restauration", "service": "chatbot-ia", "title": "Argumentaire — Chatbot IA · Restauration", "position": 30, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Un client demande si vous êtes ouverts le dimanche. L'assistant répond à 23 h, avec vos vrais horaires.<br><em>Conseil : l'exemple le plus parlant de tout le catalogue. Gardez-le en premier.</em></li><li>Il prend la réservation et l'envoie dans votre planning, avec une confirmation automatique.<br><em>Conseil : le client a sa réponse, vous avez la table remplie.</em></li><li>En cas de demande de groupe ou d'événement privé, il passe la main à un humain.<br><em>Conseil : les demandes de groupes sont les plus rentables : l'humain doit les voir.</em></li></ul>"}
{"code": "arg-chatbot-ia-services-b2b", "type": "argumentaire", "sector": "services-b2b", "service": "chatbot-ia", "title": "Argumentaire — Chatbot IA · Services B2B", "position": 40, "content": "<p>Ce que ça change concrètement chez ce type d'entreprise :</p><ul><li>Un prospect arrive sur votre site à 21 h, après avoir comparé trois prestataires. L'assistant répond et prend le rendez-vous.<br><em>Conseil : en B2B, la réactivité est souvent le critère de choix.</em></li><li>Il qualifie : taille d'entreprise, besoin, budget approximatif, échéance. Votre commercial arrive préparé.<br><em>Conseil : un commercial qui arrive préparé convertit mieux. C'est l'argument à donner.</em></li><li>Il ne promet jamais de prix et ne s'engage sur rien. Il oriente et transmet.<br><em>Conseil : les promesses de l'assistant sont limitées volontairement.</em></li></ul>"}
